126	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
127	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
128	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
129	        if (sharesHousehold) {
130	            this.clinicService.assignHousehold(owner);
131	        }
132	        this.clinicService.saveOwner(owner);
